// Helper: cari chapter berdasarkan slug
export function cariChapterBySlug(slug: string): InfoChapter | undefined {
  return daftarChapter.find(c => c.slug === slug)
}

// Helper: ambil semua chapter dari satu GrupBab
export function chapterByGrup(grupBab: number): InfoChapter[] {
  return daftarChapter.filter(c => c.grupBab === grupBab)
}

// Semua kategori unik
export const semuaKategori = [...new Set(daftarChapter.map(c => c.kategori))].sort()
